local Kx="" for i=1,#kT do Kx=Kx..Gd[kT[i]] end
local SN=qJ and qJ[Kx]
local UX=type(SN)=="function"
if UX then
local AH={8,15,15,11,6,21,14,3,20,9,15,14}
local Mb="" for i=1,#AH do Mb=Mb..Gd[AH[i]] end
local WZ={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local Gt="" for i=1,#WZ do Gt=Gt..Gd[WZ[i]] end
local yp=qJ[Mb]
local gb=qJ[Gt]
local sb=false
if type(yp)=="function" and type(gb)=="function" then
local SB=function() return 5 end
local An=pcall(yp,SB,function() return -777 end)
if An and SB()==-777 then
local SZ=pcall(gb,SB)
sb=(SZ and SB()==5)
end
if not sb then pcall(gb,SB) end
if not sb and type(qJ.math)=="table" and type(qJ.math.abs)=="function" then
local Wh=qJ.math.abs
if Wh(5)==5 then
local QT,Ct=pcall(yp,Wh,function() return -777 end)
if QT and Wh(5)==-777 then
local AX=pcall(gb,Wh)
sb=(AX and Wh(5)==5)
if not sb then pcall(gb,Wh) qJ.math.abs=(type(Ct)=="function" and Ct) or function(v) if v<0 then return -v end return v end end
end
end
end
if sb then
local cr={SN,yp,gb}
local YH=qJ.string
if type(YH)=="table" then
cr[#cr+1]=YH.char cr[#cr+1]=YH.byte cr[#cr+1]=YH.sub cr[#cr+1]=YH.rep cr[#cr+1]=YH.len
end
if type(qJ.table)=="table" and qJ.table.concat then cr[#cr+1]=qJ.table.concat end
if qJ.pcall then cr[#cr+1]=qJ.pcall end
if type(qJ.math)=="table" and qJ.math.floor then cr[#cr+1]=qJ.math.floor end
for CZ=1,#cr do local zt=cr[CZ] if type(zt)=="function" then pcall(gb,zt) end end
end
end
end
if not UX then return nil end

